function transactionPayments(tid){return state.data.payments.filter(p=>p.transaction_id===tid&&(p.payment_direction||'in')==='in')}
function transactionPaid(tid){return transactionPayments(tid).reduce((s,p)=>s+Number(p.amount||0),0)}
function transactionDue(t){return Math.max(0,Number(t?.total_amount||0)-transactionPaid(t?.id))}
function transactionPaymentInfo(t){
  const total=Number(t?.total_amount||0),paid=transactionPaid(t?.id),due=Math.max(0,total-paid);
  if(total<=0)return {status:'Paid',paid,due:0,className:'paid',label:'Paid'};
  if(paid<=0)return {status:'Unpaid',paid:0,due:total,className:'unpaid',label:`Unpaid — Due ${money(total)}`};
  if(paid+0.005<total)return {status:'Partial',paid,due,className:'partial',label:`Partial — Paid ${money(paid)} / Due ${money(due)}`};
  if(paid>total+0.005)return {status:'Overpaid',paid,due:0,className:'paid',label:`Overpaid — ${money(paid-total)} credit`};
  return {status:'Paid',paid,due:0,className:'paid',label:'Paid'};
}
function paymentBadge(t){const p=transactionPaymentInfo(t);return `<span class="badge ${p.className}">${esc(p.label)}</span>`}
function localToday(){const d=new Date();d.setHours(0,0,0,0);return d}
