function dateFilterRows(rows,field,key){const f=state.filters[key]||{year:'',month:''};return rows.filter(r=>{const v=String(r[field]||'');if(!v)return !f.year&&!f.month;const y=v.slice(0,4),m=v.slice(5,7);return (!f.year||y===f.year)&&(!f.month||m===f.month)})}
function dateFilterHtml(rows,field,key){const f=state.filters[key]||{year:'',month:''},years=availableYears(rows,field),months=['01','02','03','04','05','06','07','08','09','10','11','12'],names=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];return `<div class="table-filters" data-filter-key="${key}"><label>Year<select class="filter-year"><option value="">All Years</option>${years.map(y=>`<option value="${y}" ${f.year===y?'selected':''}>${y}</option>`).join('')}</select></label><label>Month<select class="filter-month"><option value="">All Months</option>${months.map((m,i)=>`<option value="${m}" ${f.month===m?'selected':''}>${names[i]}</option>`).join('')}</select></label><button class="btn small filter-clear" type="button">Clear</button></div>`}
function bindDateFilter(key,rerender){const box=$(`[data-filter-key="${key}"]`);if(!box)return;const year=$('.filter-year',box),month=$('.filter-month',box);const apply=()=>{state.filters[key]={year:year.value,month:month.value};rerender()};year.onchange=apply;month.onchange=apply;$('.filter-clear',box).onclick=()=>{state.filters[key]={year:'',month:''};rerender()}}
