function transactionCategoryName(t){return state.data.transactionCategories.find(c=>c.id===t.transaction_category_id)?.name||t.transaction_category||''}
function transactionCategoryOptions(selected){return bData('transactionCategories').filter(c=>c.active!==false).sort((a,b)=>alpha(a.name,b.name)).map(c=>`<option value="${c.id}" ${selected===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}
function transactionFilterHtml(rows,key){const f=state.filters[key]||{year:'',month:'',category:'',payment:''};const years=availableYears(rows,'event_date'),months=['01','02','03','04','05','06','07','08','09','10','11','12'],names=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];const cats=bData('transactionCategories').filter(c=>c.active!==false).sort((a,b)=>alpha(a.name,b.name));const catFilter=state.business==='njs'?`<label>Event Category<select class="filter-category"><option value="">All Categories</option>${cats.map(c=>`<option value="${c.id}" ${f.category===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>`:'';return `<div class="table-filters tx-filters" data-tx-filter-key="${key}"><label>Year<select class="filter-year"><option value="">All Years</option>${years.map(y=>`<option value="${y}" ${f.year===y?'selected':''}>${y}</option>`).join('')}</select></label><label>Month<select class="filter-month"><option value="">All Months</option>${months.map((m,i)=>`<option value="${m}" ${f.month===m?'selected':''}>${names[i]}</option>`).join('')}</select></label>${catFilter}<label>Payment<select class="filter-payment"><option value="">All Statuses</option><option value="Paid" ${f.payment==='Paid'?'selected':''}>Paid</option><option value="Partial" ${f.payment==='Partial'?'selected':''}>Partial</option><option value="Unpaid" ${f.payment==='Unpaid'?'selected':''}>Unpaid</option><option value="Overpaid" ${f.payment==='Overpaid'?'selected':''}>Overpaid</option></select></label><button class="btn small tx-filter-clear" type="button">Clear</button></div>`}
function applyTransactionFilters(rows,key){const f=state.filters[key]||{};return rows.filter(t=>{const v=String(t.event_date||''),pi=transactionPaymentInfo(t);return (!f.year||v.slice(0,4)===f.year)&&(!f.month||v.slice(5,7)===f.month)&&(state.business!=='njs'||!f.category||t.transaction_category_id===f.category)&&(!f.payment||pi.status===f.payment)})}
function bindTransactionFilters(key,rerender){const box=$(`[data-tx-filter-key="${key}"]`);if(!box)return;const apply=()=>{state.filters[key]={year:$('.filter-year',box)?.value||'',month:$('.filter-month',box)?.value||'',category:$('.filter-category',box)?.value||'',payment:$('.filter-payment',box)?.value||''};rerender()};$$('select',box).forEach(s=>s.onchange=apply);$('.tx-filter-clear',box).onclick=()=>{state.filters[key]={year:'',month:'',category:'',payment:''};rerender()}}
function isPrinterItem(i){if(!i||i.business_code!=='njs')return false;const cat=state.data.inventoryCategories.find(c=>c.id===i.category_id)?.name||i.category||'';return i.item_kind==='printer'||/printer/i.test(cat)||/printer/i.test(i.name||'')}
function printerItems(){return bData('inventory').filter(isPrinterItem).sort((a,b)=>alpha(a.name,b.name))}
function printerAvailability(printerId,eventDate,currentTxId=null){const p=state.data.inventory.find(i=>i.id===printerId);if(!p)return {available:false,reason:'Printer not found'};const blocked=['Damaged','For Repair','Under Repair','Missing','Unavailable'].includes(p.status);if(blocked)return {available:false,reason:p.status};const activeRepair=state.data.repairs.some(r=>r.inventory_item_id===printerId&&!['Repaired'].includes(r.repair_status||'')&&!r.date_repaired);if(activeRepair)return {available:false,reason:'Under repair'};if(eventDate){const conflict=state.data.transactions.find(t=>t.business_code==='njs'&&t.id!==currentTxId&&t.printer_id===printerId&&t.event_date===eventDate&&t.status!=='Cancelled');if(conflict)return {available:false,reason:`Booked ${conflict.client_name_snapshot||''}`.trim()}}return {available:true,reason:'Available'}}
function printerOptions(selected,eventDate,currentTxId=null){return printerItems().map(p=>{const a=printerAvailability(p.id,eventDate,currentTxId);return `<option value="${p.id}" ${selected===p.id?'selected':''} ${!a.available&&selected!==p.id?'disabled':''}>${esc(p.name)} — ${esc(a.reason)}</option>`}).join('')}
