  const expenses=expView.reduce((sum,x)=>sum+Number(x.amount||0),0),receivable=tx.reduce((sum,t)=>sum+transactionDue(t),0),contracted=tx.reduce((sum,t)=>sum+Number(t.total_amount||0),0);
  const today=localToday(),todayStr=new Date().toISOString().slice(0,10);
  const upcoming=tx.filter(t=>{const d=dateValue(t.event_date);return d&&d>=today&&!['Completed','Cancelled'].includes(t.status)}).sort((a,b)=>String(a.event_date).localeCompare(String(b.event_date))||String(a.start_time||'').localeCompare(String(b.start_time||''))).slice(0,8);
  const todayEvents=txAll.filter(t=>t.event_date===todayStr&&!['Cancelled'].includes(t.status));
  const activeEquipment=inv.reduce((sum,i)=>sum+inventoryQtyStats(i).available,0);
