function clientForm(id){const x=state.data.clients.find(v=>v.id===id)||{};modal(`${id?'Edit':'Add'} Client`,`<form id="clientForm" class="stack-form"><label>Name<input id="cName" value="${esc(x.name||'')}" required></label><label>Contact<input id="cContact" value="${esc(x.contact||'')}"></label><label>Email<input id="cEmail" type="email" value="${esc(x.email||'')}"></label><label>Notes<textarea id="cNotes">${esc(x.notes||'')}</textarea></label><div class="form-actions"><button type="button" class="btn" data-close>Cancel</button><button class="btn primary">Save</button></div></form>`);$('#clientForm').onsubmit=async e=>{e.preventDefault();const row={business_code:state.business,name:$('#cName').value.trim(),contact:$('#cContact').value.trim(),email:$('#cEmail').value.trim(),notes:$('#cNotes').value.trim()};const q=id?sb.from('clients').update(row).eq('id',id):sb.from('clients').insert(row);const {error}=await q;if(error)return toast(error.message,'error');await audit(id?'UPDATE':'CREATE','clients',id||'',row);toast('Client saved.');closeModal();await loadAll();render()}}
async function archiveClient(id){const {error}=await sb.from('clients').update({archived:true}).eq('id',id);if(error)return toast(error.message,'error');await audit('ARCHIVE','clients',id);toast('Client archived.');await loadAll();render()}
function requestDeleteClient(id){const client=state.data.clients.find(x=>x.id===id);if(!client)return;const linked=state.data.transactions.filter(t=>t.client_id===id);const msg=linked.length?`Delete ${client.name}? This client has ${linked.length} historical ${linked.length===1?txLabel().toLowerCase():txLabel().toLowerCase()+'s'}. The event booking names will be preserved, but the client link will be removed.`:`Permanently delete ${client.name}? This cannot be undone.`;confirmModal('Delete Client',msg,()=>deleteClient(id))}
async function deleteClient(id){const client=state.data.clients.find(x=>x.id===id);const linked=state.data.transactions.filter(t=>t.client_id===id);if(linked.length){const {error:updateError}=await sb.from('transactions').update({client_id:null}).eq('client_id',id);if(updateError)return toast(updateError.message,'error')}const {error}=await sb.from('clients').delete().eq('id',id);if(error)return toast(error.message,'error');await audit('DELETE','clients',id,{name:client?.name||'',historical_records_preserved:linked.length});toast('Client deleted. Historical event booking summaries were preserved.');await loadAll();render()}
function openCategoryManager(){const all=[...bData('categories')].sort((a,b)=>alpha(a.name,b.name));const q=String(state.search.categories||'').trim().toLowerCase();const rows=q?all.filter(x=>(`${x.name||''} ${x.remarks||''}`).toLowerCase().includes(q)):all;modal(`Manage ${catalogLabel()} Categories`,`<div class="panel modal-panel"><div class="panel-head"><div><h2>${catalogLabel()} Categories</h2><p class="muted">Reusable categories for service packages.</p></div><button class="btn primary" id="addCategoryInside">+ Add Category</button></div><div class="toolbar">${searchHtml('categories','Search categories...')}</div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Name</th><th>Status</th><th>Remarks</th><th>Actions</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.active===false?'Inactive':'Active'}</td><td>${esc(x.remarks||'')}</td><td class="nowrap"><button class="btn small" data-editcatinside="${x.id}">Edit</button> <button class="btn small danger" data-delcatinside="${x.id}">Remove</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No categories.</div>'}</div><div class="form-actions"><button class="btn" data-close>Close</button></div>`,{wide:true});bindSearch('categories',openCategoryManager);$('#addCategoryInside').onclick=()=>categoryForm(null,true);$$('[data-editcatinside]').forEach(b=>b.onclick=()=>categoryForm(b.dataset.editcatinside,true));$$('[data-delcatinside]').forEach(b=>b.onclick=()=>confirmModal('Remove Category','Remove this category? Existing packages will keep their historical data but lose the category link.',async()=>{await deleteCategory(b.dataset.delcatinside);openCategoryManager()}))}
function renderCategories(){head(`${catalogLabel()} Categories`,`Reusable categories.`);let rows=[...bData('categories')].sort((a,b)=>alpha(a.name,b.name));rows=searchRows(rows,'categories');$('#viewRoot').innerHTML=`<div class="panel"><div class="panel-head"><h2>Category Library</h2><div class="toolbar">${searchHtml('categories','Search categories...')}<button class="btn primary" id="addMaster">+ Add Category</button></div></div>${rows.length?masterTable('categories',rows,'Category',''): '<div class="empty">No categories.</div>'}</div>`;bindSearch('categories',renderCategories);$('#addMaster').onclick=()=>categoryForm();$$('[data-editmaster]').forEach(b=>b.onclick=()=>categoryForm(b.dataset.editmaster));$$('[data-delmaster]').forEach(b=>b.onclick=()=>confirmModal('Remove Category','Remove this category?',()=>deleteCategory(b.dataset.delmaster)))}
