function couponUsageCount(id,currentTxId=null){return bData('transactions').filter(t=>t.coupon_id===id&&t.id!==currentTxId&&t.status!=='Cancelled').length}
function couponValidity(coupon,subtotal,currentTxId=null){
  if(!coupon||coupon.active===false)return {ok:false,reason:'Inactive coupon'};
  const today=new Date().toISOString().slice(0,10);if(coupon.start_date&&today<coupon.start_date)return {ok:false,reason:'Coupon is not yet valid'};if(coupon.end_date&&today>coupon.end_date)return {ok:false,reason:'Coupon has expired'};
  if(Number(coupon.minimum_amount||0)>Number(subtotal||0))return {ok:false,reason:`Minimum booking amount is ${money(coupon.minimum_amount)}`};
  if(Number(coupon.usage_limit||0)>0&&couponUsageCount(coupon.id,currentTxId)>=Number(coupon.usage_limit))return {ok:false,reason:'Coupon usage limit reached'};
  return {ok:true,reason:'Valid'};
}
function calculateCouponDiscount(coupon,subtotal,currentTxId=null){const valid=couponValidity(coupon,subtotal,currentTxId);if(!valid.ok)return {discount:0,...valid};let d=coupon.discount_type==='fixed'?Number(coupon.discount_value||0):Number(subtotal||0)*(Number(coupon.discount_value||0)/100);if(Number(coupon.max_discount||0)>0)d=Math.min(d,Number(coupon.max_discount));d=Math.min(d,Number(subtotal||0));return {ok:true,reason:'Applied',discount:Math.max(0,d)}}
function renderCoupons(){head('Coupons & Vouchers','Create voucher codes that automatically discount eligible event bookings.');let rows=[...bData('coupons')].sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||'')));rows=searchRows(rows,'coupons');$('#viewRoot').innerHTML=`<div class="panel"><div class="panel-head"><div><h2>Coupon / Voucher Codes</h2><p class="muted">Generate fixed-amount or percentage discounts with validity, minimum spend and usage limits.</p></div><div class="toolbar">${searchHtml('coupons','Search code, name or remarks...')}<button class="btn primary" id="addCoupon">+ Create Coupon</button></div></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Code</th><th>Name</th><th>Discount</th><th>Validity</th><th>Minimum</th><th>Usage</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(c=>`<tr><td><code><strong>${esc(c.code)}</strong></code></td><td>${esc(c.name||'—')}</td><td>${c.discount_type==='fixed'?money(c.discount_value):`${Number(c.discount_value||0)}%`}${Number(c.max_discount||0)>0?`<div class="muted">Max ${money(c.max_discount)}</div>`:''}</td><td>${esc(c.start_date||'Any')} – ${esc(c.end_date||'No expiry')}</td><td>${money(c.minimum_amount)}</td><td>${couponUsageCount(c.id)}${Number(c.usage_limit||0)>0?` / ${Number(c.usage_limit)}`:' / Unlimited'}</td><td><span class="badge ${c.active!==false?'good':''}">${c.active!==false?'Active':'Inactive'}</span></td><td class="nowrap"><button class="btn small" data-editcoupon="${c.id}">Edit</button> <button class="btn small danger" data-delcoupon="${c.id}">Remove</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No coupon codes yet.</div>'}</div>`;bindSearch('coupons',renderCoupons);$('#addCoupon').onclick=()=>couponForm();$$('[data-editcoupon]').forEach(b=>b.onclick=()=>couponForm(b.dataset.editcoupon));$$('[data-delcoupon]').forEach(b=>b.onclick=()=>confirmModal('Remove Coupon','Remove this coupon? Existing bookings will keep the coupon code and discount snapshot.',()=>deleteCoupon(b.dataset.delcoupon)))}
function generateCouponCode(){const chars='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';let x='NJS-';for(let i=0;i<8;i++)x+=chars[Math.floor(Math.random()*chars.length)];return x}
function couponForm(id=null){const c=state.data.coupons.find(x=>x.id===id)||{};modal(`${id?'Edit':'Create'} Coupon / Voucher`,`<form id="couponForm" class="form-grid"><label>Coupon Code<div class="inline-actions"><input id="couponCode" value="${esc(c.code||generateCouponCode())}" required><button type="button" class="btn" id="regenCoupon">Generate</button></div></label><label>Voucher Name<input id="couponName" value="${esc(c.name||'')}" placeholder="e.g. Wedding Promo"></label><label>Discount Type<select id="couponType"><option value="percentage" ${c.discount_type!=='fixed'?'selected':''}>Percentage (%)</option><option value="fixed" ${c.discount_type==='fixed'?'selected':''}>Fixed Amount (₱)</option></select></label><label>Discount Value<input id="couponValue" type="number" min="0" step="0.01" value="${Number(c.discount_value||0)}" required></label><label>Minimum Booking Amount<input id="couponMinimum" type="number" min="0" step="0.01" value="${Number(c.minimum_amount||0)}"></label><label>Maximum Discount<input id="couponMax" type="number" min="0" step="0.01" value="${Number(c.max_discount||0)}" placeholder="0 = no maximum"></label><label>Valid From<input id="couponStart" type="date" value="${esc(c.start_date||'')}"></label><label>Valid Until<input id="couponEnd" type="date" value="${esc(c.end_date||'')}"></label><label>Usage Limit<input id="couponLimit" type="number" min="0" step="1" value="${Number(c.usage_limit||0)}" placeholder="0 = unlimited"></label><label>Status<select id="couponActive"><option value="true" ${c.active!==false?'selected':''}>Active</option><option value="false" ${c.active===false?'selected':''}>Inactive</option></select></label><label class="full">Remarks<textarea id="couponRemarks">${esc(c.remarks||'')}</textarea></label><div class="form-actions full"><button type="button" class="btn" data-close>Cancel</button><button class="btn primary">Save Coupon</button></div></form>`);$('#regenCoupon').onclick=()=>{$('#couponCode').value=generateCouponCode()};$('#couponForm').onsubmit=async e=>{e.preventDefault();const row={business_code:state.business,code:$('#couponCode').value.trim().toUpperCase(),name:$('#couponName').value.trim()||null,discount_type:$('#couponType').value,discount_value:Number($('#couponValue').value||0),minimum_amount:Number($('#couponMinimum').value||0),max_discount:Number($('#couponMax').value||0),start_date:$('#couponStart').value||null,end_date:$('#couponEnd').value||null,usage_limit:Number($('#couponLimit').value||0),active:$('#couponActive').value==='true',remarks:$('#couponRemarks').value.trim()||null,created_by:c.created_by||state.user.id};const {data,error}=await(id?sb.from('coupons').update(row).eq('id',id).select().maybeSingle():sb.from('coupons').insert(row).select().maybeSingle());if(error)return toast(error.message,'error');await audit(id?'UPDATE':'CREATE','coupons',id||(data&&data.id)||'',{code:row.code,discount_type:row.discount_type,discount_value:row.discount_value});toast('Coupon saved.');closeModal();await loadAll();render()}}
