  const rows=all;
  modal('Equipment Types',`<div class="panel modal-panel"><div class="panel-head"><div><h2>Equipment Types</h2><p class="muted">Generic package requirements such as Speakers, Subwoofer, Mixer, Microphone, Moving Head or LED Wall.</p></div><button class="btn primary" id="addEquipmentType">+ Add Equipment Type</button></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Type</th><th>Category</th><th>Status</th><th>Remarks</th><th>Actions</th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${esc(state.data.inventoryCategories.find(c=>c.id===x.category_id)?.name||'—')}</td><td>${x.active===false?'Inactive':'Active'}</td><td>${esc(x.remarks||'')}</td><td class="nowrap"><button class="btn small" data-edittype="${x.id}">Edit</button> <button class="btn small danger" data-deltype="${x.id}">Remove</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No equipment types yet.</div>'}</div><div class="form-actions"><button class="btn" data-close>Close</button></div>`,{wide:true});
