function inventoryCategoryForm(id=null){
  const x=state.data.inventoryCategories.find(v=>v.id===id)||{};
  modal(`${id?'Edit':'Add'} Equipment Category`,`<form id="invCatForm" class="stack-form"><label>Category Name<input id="invCatName" value="${esc(x.name||'')}" required></label><label>Status<select id="invCatActive"><option value="true" ${x.active!==false?'selected':''}>Active</option><option value="false" ${x.active===false?'selected':''}>Inactive</option></select></label><label>Remarks<textarea id="invCatRemarks">${esc(x.remarks||'')}</textarea></label><div class="form-actions"><button type="button" class="btn" id="backToInvCats">Back</button><button class="btn primary">Save Category</button></div></form>`);
  $('#backToInvCats').onclick=()=>manageInventoryCategories();
  $('#invCatForm').onsubmit=async e=>{
    e.preventDefault();
    if(!requirePermission('inventory',id?'edit':'add'))return;
    const row={business_code:state.business,name:$('#invCatName').value.trim(),active:$('#invCatActive').value==='true',remarks:$('#invCatRemarks').value.trim()||null};
    const query=id?sb.from('inventory_categories').update(row).eq('id',id).select().maybeSingle():sb.from('inventory_categories').insert(row).select().maybeSingle();
    const {data,error}=await query;
    if(error)return toast(`Equipment category was not saved: ${error.message}`,'error');
    await audit(id?'UPDATE':'CREATE','inventory_categories',id||(data&&data.id)||'',row);
    toast(`Equipment category ${id?'updated':'added'} successfully.`);
    await loadAll();
    manageInventoryCategories();
  };
}
async function deleteInventoryCategory(id){const x=state.data.inventoryCategories.find(v=>v.id===id);const {error}=await sb.from('inventory_items').update({category_id:null}).eq('category_id',id);if(error)return toast(error.message,'error');const {error:e2}=await sb.from('inventory_categories').delete().eq('id',id);if(e2)return toast(e2.message,'error');await audit('DELETE','inventory_categories',id,{name:x?.name||''});toast('Inventory category removed.');await loadAll();render()}
async function deleteInventory(id){const item=state.data.inventory.find(x=>x.id===id);const linked=state.data.checklist.filter(x=>x.inventory_item_id===id);if(linked.length){const {error}=await sb.from('inventory_items').update({status:'Unavailable'}).eq('id',id);if(error)return toast(error.message,'error');await audit('ARCHIVE','inventory_items',id,{name:item?.name||'',reason:'Used in transaction checklist',checklist_links:linked.length});toast('This item is used in booking/appointment history, so it was marked Unavailable instead of deleted.','warning')}else{const {error}=await sb.from('inventory_items').delete().eq('id',id);if(error)return toast(error.message,'error');await audit('DELETE','inventory_items',id,{name:item?.name||''});toast('Inventory item deleted.')}await loadAll();render()}
function dispatchStatusClass(status){return status==='Returned'?'ready':status==='Out'||status==='Partially Out'||status==='Partially Returned'?'partial':status==='Missing'||status==='Damaged'?'damaged':''}
function dispatchRequirementSummary(txid){
  const reqs=state.data.transactionTypeRequirements.filter(r=>r.transaction_id===txid);
  const checks=state.data.checklist.filter(c=>c.transaction_id===txid);
  const genericRequired=reqs.reduce((s,r)=>s+Number(r.required_quantity||0),0);
  const specificRequired=checks.reduce((s,c)=>s+checklistSpecificQty(c),0);
  return {reqs,checks,genericRequired,specificRequired,totalRequired:genericRequired+specificRequired,out:checks.reduce((s,c)=>s+checklistOutNow(c),0),returned:checks.reduce((s,c)=>s+Number(c.returned_quantity||0),0),issues:checks.reduce((s,c)=>s+Number(c.damaged_quantity||0)+Number(c.missing_quantity||0),0)}
}
function renderDispatch(){
  head('Equipment Dispatch',String(state.profile?.role||'').toLowerCase()==='staff'?'Select a booking/event, then scan equipment OUT or RETURN using phone QR, barcode scanner, or manual code.':'Packages request generic equipment types; scan the actual brand/model you decide to bring.');
  const bookings=bData('transactions').filter(t=>t.status!=='Cancelled').sort((a,b)=>String(a.event_date||'').localeCompare(String(b.event_date||'')));
  const rows=bookings.map(t=>({t,...dispatchRequirementSummary(t.id)}));
  $('#viewRoot').innerHTML=`<div class="panel dispatch-hero"><div><span class="eyebrow">TYPE-BASED EQUIPMENT CONTROL</span><h2>Event Equipment Check-Out & Return</h2><p class="muted">Select the booking below, then scan the actual equipment. Example: Package requires Speakers × 4, and you may scan RCF × 2 + Alto × 2.</p>${String(state.profile?.role||'').toLowerCase()==='staff'?'<div class="staff-dispatch-guide"><strong>Staff workflow:</strong> 1) Choose event • 2) CHECK OUT before leaving • 3) RETURN / IN after the event • 4) Scan every item one unit at a time.</div>':''}</div></div><div class="panel"><div class="panel-head"><div><h2>Booking Dispatch Board</h2><p class="muted">Required Qty includes generic Equipment Types plus any specific equipment/add-ons.</p></div></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Event Date</th><th>Client / Event</th><th>Package</th><th>Required Qty</th><th>Currently Out</th><th>Returned Scans</th><th>Issues</th><th>Action</th></tr></thead><tbody>${rows.map(({t,totalRequired,out,returned,issues})=>`<tr><td>${esc(t.event_date||'')}</td><td><strong>${esc(t.client_name_snapshot||'')}</strong><br><small>${esc(t.venue||'')}</small></td><td>${esc(t.item_name_snapshot||'')}</td><td>${totalRequired}</td><td>${out}</td><td>${returned}</td><td>${issues?`<span class="badge damaged">${issues}</span>`:'0'}</td><td><button class="btn primary small" data-dispatch="${t.id}">Scan Equipment</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No bookings available.</div>'}</div>`;
  $$('[data-dispatch]').forEach(b=>b.onclick=()=>openDispatchScanner(b.dataset.dispatch))
}
async function stopMobileScanner(){if(!activeQrScanner)return;try{await activeQrScanner.stop()}catch(_){ }try{await activeQrScanner.clear()}catch(_){ }activeQrScanner=null}
async function startMobileScanner(txid){
  const feedback=$('#scanFeedback'),reader=$('#mobileQrReader'),startBtn=$('#startPhoneScan');
  if(!reader||!feedback)return;
  const setFeedback=(msg,type='')=>{feedback.textContent=msg;feedback.className='scan-feedback '+type};
  if(startBtn){startBtn.disabled=true;startBtn.textContent='📷 Starting Camera…'}
  try{
    if(!window.isSecureContext){
      throw new Error('Camera access requires HTTPS. Open the deployed GitHub Pages https:// address, not a local file or http:// link.');
    }
    if(!navigator.mediaDevices||typeof navigator.mediaDevices.getUserMedia!=='function'){
      throw new Error('This browser does not provide camera access. Try Chrome/Edge on Android or Safari/Chrome on iPhone and allow Camera permission.');
    }
    if(typeof Html5Qrcode==='undefined'){
      throw new Error('QR scanner library did not load. Refresh the page while online, then try again.');
    }

    await stopMobileScanner();
    reader.classList.remove('hidden');
    setFeedback('Requesting camera permission… Please tap Allow if your phone asks.','warning');

    // Ask permission from the user gesture first. This makes mobile Safari/Chrome
    // show a clear permission prompt before html5-qrcode takes over the camera.
    let permissionStream=null;
    try{
      permissionStream=await navigator.mediaDevices.getUserMedia({
        video:{facingMode:{ideal:'environment'}},
        audio:false
      });
    }finally{
      if(permissionStream)permissionStream.getTracks().forEach(t=>t.stop());
    }

    activeQrScanner=new Html5Qrcode('mobileQrReader');

    const onDecoded=async decoded=>{
      if(window.__scanBusy)return;
      window.__scanBusy=true;
      try{
        await processDispatchScan(
          txid,
          String(decoded||'').trim().toUpperCase(),
          $('#scanMode').value,
          'phone-camera'
        );
      }finally{
        setTimeout(()=>window.__scanBusy=false,700);
      }
    };

    // Prefer the rear/environment camera without needing camera labels.
    try{
      await activeQrScanner.start(
        {facingMode:'environment'},
        {fps:10,qrbox:(vw,vh)=>({width:Math.min(260,Math.floor(vw*.72)),height:Math.min(260,Math.floor(vh*.72))}),aspectRatio:1.0},
        onDecoded,
        ()=>{}
      );
    }catch(primaryErr){
      // Fallback for phones that require an explicit device id.
      try{await activeQrScanner.clear()}catch(_){}
      activeQrScanner=null;
      const cameras=await Html5Qrcode.getCameras();
      if(!cameras?.length)throw primaryErr;
      const rear=cameras.find(c=>/back|rear|environment/i.test(c.label))||cameras[cameras.length-1];
      activeQrScanner=new Html5Qrcode('mobileQrReader');
      await activeQrScanner.start(
        rear.id,
        {fps:10,qrbox:{width:240,height:240},aspectRatio:1.0},
        onDecoded,
        ()=>{}
      );
    }

    setFeedback('Camera ready ✓ Point it at the equipment QR code.','success');
  }catch(err){
    console.error('Phone scanner error:',err);
    const name=err?.name||'';
    let msg=err?.message||String(err);
    if(name==='NotAllowedError'||/permission|denied|notallowed/i.test(msg)){
      msg='Camera permission was blocked. Open your browser Site Settings for this GitHub Pages site, allow Camera, then tap Scan with Phone Camera again.';
    }else if(name==='NotFoundError'||/no camera|not found/i.test(msg)){
      msg='No usable camera was found on this device.';
    }else if(name==='NotReadableError'||/in use|could not start|notreadable/i.test(msg)){
      msg='The camera is being used by another app/browser tab. Close it there, then try again.';
    }
    setFeedback(`Camera unavailable: ${msg}`,'error');
    await stopMobileScanner();
    reader.classList.add('hidden');
  }finally{
    if(startBtn){startBtn.disabled=false;startBtn.textContent='📷 Scan with Phone Camera'}
  }
}
function dispatchTypeRows(txid){
  const reqs=state.data.transactionTypeRequirements.filter(r=>r.transaction_id===txid).sort((a,b)=>alpha(equipmentTypeName(a.equipment_type_id),equipmentTypeName(b.equipment_type_id)));
  if(!reqs.length)return '<tr><td colspan="5">No generic equipment type requirements for this booking.</td></tr>';
  return reqs.map(r=>{
    const required=Number(r.required_quantity||0),allocated=typeAllocatedForTransaction(txid,r.equipment_type_id),out=typeOutForTransaction(txid,r.equipment_type_id);
    const selected=state.data.checklist.filter(c=>c.transaction_id===txid&&c.equipment_type_id===r.equipment_type_id&&checklistTypeAllocated(c)>0).map(c=>{const i=state.data.inventory.find(x=>x.id===c.inventory_item_id);return `${i?.name||'Equipment'} × ${checklistTypeAllocated(c)}`}).join(', ');
    return `<tr><td><strong>${esc(equipmentTypeName(r.equipment_type_id))}</strong></td><td>${required}</td><td>${allocated}</td><td>${out}</td><td>${esc(selected||'Scan actual equipment to choose')}</td></tr>`
  }).join('')
}
function dispatchActualRows(txid){
  const checks=state.data.checklist.filter(c=>c.transaction_id===txid);
  if(!checks.length)return '<tr><td colspan="8">No actual equipment selected/scanned yet.</td></tr>';
  return checks.sort((a,b)=>alpha(state.data.inventory.find(i=>i.id===a.inventory_item_id)?.name,state.data.inventory.find(i=>i.id===b.inventory_item_id)?.name)).map(c=>{
    const item=state.data.inventory.find(i=>i.id===c.inventory_item_id);
    return `<tr data-check-row="${c.id}"><td><strong>${esc(item?.name||'Unknown Equipment')}</strong></td><td>${esc(equipmentTypeName(item?.equipment_type_id||c.equipment_type_id))}</td><td><code>${esc(item?.asset_code||'No code')}</code></td><td>${checklistSpecificQty(c)}</td><td>${checklistTypeAllocated(c)}</td><td>${checklistOutNow(c)}</td><td>${Number(c.returned_quantity||0)}</td><td><span class="badge ${dispatchStatusClass(checklistDerivedStatus(c))}">${esc(checklistDerivedStatus(c))}</span></td></tr>`
  }).join('')
}
function updateDispatchModal(txid){
  const s=dispatchRequirementSummary(txid);
  if($('#dispatchTypeRows'))$('#dispatchTypeRows').innerHTML=dispatchTypeRows(txid);
  if($('#dispatchRows'))$('#dispatchRows').innerHTML=dispatchActualRows(txid);
  if($('#dAssigned'))$('#dAssigned').textContent=s.totalRequired;
  if($('#dOut'))$('#dOut').textContent=s.out;
  if($('#dReturned'))$('#dReturned').textContent=s.returned;
  if($('#dIssues'))$('#dIssues').textContent=s.issues;
}
function openDispatchScanner(txid){
  const tx=state.data.transactions.find(t=>t.id===txid);if(!tx)return;
  const s=dispatchRequirementSummary(txid);
  modal('Equipment Dispatch Scanner',`<div class="dispatch-event-head"><div><span class="eyebrow">${esc(tx.event_date||'')}</span><h3>${esc(tx.client_name_snapshot||'Event')}</h3><p>${esc(tx.item_name_snapshot||'')} • ${esc(tx.venue||'No venue')}</p></div></div>
  <div class="scanner-console"><label>Scan Mode<select id="scanMode"><option value="out">CHECK OUT — Going to Event</option><option value="return">RETURN / IN — Back from Event</option></select></label><div class="mobile-scan-actions"><button type="button" class="btn primary" id="startPhoneScan">📷 Scan with Phone Camera</button><button type="button" class="btn" id="stopPhoneScan">Stop Camera</button></div><div id="mobileQrReader" class="mobile-qr-reader hidden"></div><label class="scanner-input-wrap">Barcode / QR / Asset Code<input id="dispatchScanInput" autocomplete="off" inputmode="text" placeholder="Ready for USB/Bluetooth scanner or manual code" autofocus></label><div class="scanner-help">For generic requirements, the equipment type determines where the scan is counted. Example: scanning RCF ART 715 counts toward Speakers if its Equipment Type is Speakers.</div><div id="scanFeedback" class="scan-feedback">Scanner ready. Logged in as ${esc(state.profile?.full_name||state.user?.email||'User')}.</div></div>
  <div class="summary-grid dispatch-summary"><div class="summary-box"><small>Total Required Qty</small><strong id="dAssigned">${s.totalRequired}</strong></div><div class="summary-box"><small>Currently Out</small><strong id="dOut">${s.out}</strong></div><div class="summary-box"><small>Returned Scans</small><strong id="dReturned">${s.returned}</strong></div><div class="summary-box"><small>Issues</small><strong id="dIssues">${s.issues}</strong></div></div>
  <h3 class="section-title">Generic Package Requirements</h3><div class="table-wrap"><table><thead><tr><th>Equipment Type</th><th>Required</th><th>Actual Selected</th><th>Out Now</th><th>Actual Equipment Used</th></tr></thead><tbody id="dispatchTypeRows">${dispatchTypeRows(txid)}</tbody></table></div>
  <h3 class="section-title">Actual Equipment / Specific Requirements</h3><div class="table-wrap"><table><thead><tr><th>Actual Equipment</th><th>Type</th><th>Scan Code</th><th>Specific Qty</th><th>Type Allocation</th><th>Out Now</th><th>Returned</th><th>Status</th></tr></thead><tbody id="dispatchRows">${dispatchActualRows(txid)}</tbody></table></div>
  <div class="form-actions"><button class="btn" id="dispatchCloseBtn">Close</button></div>`,{wide:true});
  const input=$('#dispatchScanInput');let scanTimer=null,scanBusy=false,lastKeyAt=0,rapidKeys=0;
  const submitScan=async(method='scanner/manual')=>{if(scanBusy)return;const code=input.value.trim().toUpperCase();if(!code)return;scanBusy=true;input.value='';try{await processDispatchScan(txid,code,$('#scanMode').value,method)}finally{scanBusy=false;rapidKeys=0;lastKeyAt=0;setTimeout(()=>input.focus(),30)}};
  input.onkeydown=async e=>{if(e.key==='Enter'){e.preventDefault();if(scanTimer){clearTimeout(scanTimer);scanTimer=null}await submitScan(rapidKeys>=3?'physical-barcode-scanner':'scanner/manual');return}const now=Date.now();if(e.key.length===1){rapidKeys=(now-lastKeyAt<80)?rapidKeys+1:1;lastKeyAt=now;if(scanTimer)clearTimeout(scanTimer);scanTimer=setTimeout(()=>{if(input.value.trim().length>=3&&rapidKeys>=3)submitScan('physical-barcode-scanner')},180)}};
  const scannerFocusCapture=e=>{if($('#modalBackdrop')?.classList.contains('hidden')||!$('#dispatchScanInput'))return;const tag=String(e.target?.tagName||'').toLowerCase();const editable=e.target?.isContentEditable||['input','textarea','select'].includes(tag);if(!editable&&e.key&&e.key.length===1){input.focus();input.value='';rapidKeys=0;lastKeyAt=0}};
  document.addEventListener('keydown',scannerFocusCapture,true);
  $('#startPhoneScan').onclick=async()=>{const f=$('#scanFeedback');if(f){f.textContent='Opening phone camera…';f.className='scan-feedback warning'}await startMobileScanner(txid)};
  $('#stopPhoneScan').onclick=async()=>{await stopMobileScanner();$('#mobileQrReader')?.classList.add('hidden');const f=$('#scanFeedback');if(f){f.textContent='Camera stopped. USB/Bluetooth scanner or manual code input is still ready.';f.className='scan-feedback'}};
  $('#dispatchCloseBtn').onclick=async()=>{document.removeEventListener('keydown',scannerFocusCapture,true);if(scanTimer)clearTimeout(scanTimer);await stopMobileScanner();closeModal()};
  setTimeout(()=>input.focus(),100)
}
async function processDispatchScan(txid,code,mode,scanMethod='scanner/manual'){
  const feedback=$('#scanFeedback'),item=state.data.inventory.find(i=>String(i.asset_code||'').toUpperCase()===code);
  if(!item){if(feedback){feedback.textContent=`Not found: ${code}`;feedback.className='scan-feedback error'}return}
  const now=new Date().toISOString(),typeId=item.equipment_type_id||null;
  let check=state.data.checklist.find(c=>c.transaction_id===txid&&c.inventory_item_id===item.id);
  if(mode==='out'){
    const stats=inventoryQtyStats(item);
    if(['Damaged','Missing','Unavailable'].includes(item.status)){if(feedback){feedback.textContent=`Cannot check out ${item.name}: base status is ${item.status}.`;feedback.className='scan-feedback error'}return}
    if(stats.available<=0){if(feedback){feedback.textContent=`No available quantity left for ${item.name}. Total ${stats.total}, Out ${stats.out}, Repair ${stats.repair}.`;feedback.className='scan-feedback error'}return}
    const outQty=Number(check?.out_quantity||0),specificQty=checklistSpecificQty(check),specificStillNeeded=Math.max(0,specificQty-Math.min(specificQty,outQty));
    let allocatingType=false,typeReq=null;
    if(specificStillNeeded<=0){
      if(!typeId){if(feedback){feedback.textContent=`${item.name} has no Equipment Type. Edit the inventory item first.`;feedback.className='scan-feedback error'}return}
      typeReq=typeRequiredForTransaction(txid,typeId);
      if(typeReq){
        const allocated=typeAllocatedForTransaction(txid,typeId),required=Number(typeReq.required_quantity||0);
        if(allocated<required)allocatingType=true
      }
    }
    if(!check&&!allocatingType){if(feedback){feedback.textContent=`${item.name} is not specifically assigned and ${equipmentTypeName(typeId)} is not an outstanding requirement for this booking.`;feedback.className='scan-feedback error'}return}
    if(check&&!allocatingType&&outQty>=checklistAssigned(check)){if(feedback){feedback.textContent=`No remaining requirement for ${item.name}. Generic ${equipmentTypeName(typeId)} requirement may already be complete.`;feedback.className='scan-feedback warning'}return}
    if(!check&&allocatingType){
      const {data,error}=await sb.from('transaction_checklist').insert({transaction_id:txid,inventory_item_id:item.id,equipment_type_id:typeId,status:'Assigned',assigned_quantity:1,specific_assigned_quantity:0,type_allocated_quantity:1,out_quantity:0,returned_quantity:0,checked_at:null,checked_by:null}).select().single();
      if(error)return toast(error.message,'error');check=data
    }else if(check&&allocatingType){
      const nextType=checklistTypeAllocated(check)+1,nextAssigned=checklistAssigned(check)+1;
      const {data,error}=await sb.from('transaction_checklist').update({equipment_type_id:typeId,type_allocated_quantity:nextType,assigned_quantity:nextAssigned}).eq('id',check.id).select().single();
      if(error)return toast(error.message,'error');check=data
    }
    const nextOut=Number(check.out_quantity||0)+1,next={...check,out_quantity:nextOut};
    const {error}=await sb.from('transaction_checklist').update({out_quantity:nextOut,status:checklistDerivedStatus(next),checked_out_at:now,checked_out_by:state.user.id,checked_out_method:scanMethod,checked_at:now,checked_by:state.user.id}).eq('id',check.id);
    if(error)return toast(error.message,'error');
    const reqLabel=allocatingType?`${equipmentTypeName(typeId)} ${typeAllocatedForTransaction(txid,typeId)+1}/${Number(typeReq?.required_quantity||0)}`:`Specific ${nextOut}/${checklistAssigned(check)}`;
    if(feedback){feedback.textContent=`OUT ✓ ${item.name} — ${reqLabel}`;feedback.className='scan-feedback success'}
    await audit('EQUIPMENT_OUT','transaction_checklist',check.id,{transaction_id:txid,inventory_item_id:item.id,equipment_type_id:typeId,equipment_type:equipmentTypeName(typeId),asset_code:code,quantity:1,requirement_source:allocatingType?'equipment_type':'specific',scan_method:scanMethod})
  }else{
    if(!check){if(feedback){feedback.textContent=`${item.name} was not scanned OUT for this booking.`;feedback.className='scan-feedback error'}return}
    const outQty=Number(check.out_quantity||0),returnedQty=Number(check.returned_quantity||0),outNow=Math.max(0,outQty-returnedQty);
    if(outNow<=0){if(feedback){feedback.textContent=`No unit currently OUT for ${item.name}.`;feedback.className='scan-feedback warning'}return}
    const nextReturned=returnedQty+1,next={...check,returned_quantity:nextReturned};
    const {error}=await sb.from('transaction_checklist').update({returned_quantity:nextReturned,status:checklistDerivedStatus(next),returned_at:now,returned_by:state.user.id,returned_method:scanMethod,checked_at:now,checked_by:state.user.id}).eq('id',check.id);
    if(error)return toast(error.message,'error');
    if(feedback){feedback.textContent=`IN ✓ ${item.name} — ${nextReturned}/${outQty} returned`;feedback.className='scan-feedback success'}
    await audit('EQUIPMENT_RETURN','transaction_checklist',check.id,{transaction_id:txid,inventory_item_id:item.id,equipment_type_id:typeId,equipment_type:equipmentTypeName(typeId),asset_code:code,quantity:1,scan_method:scanMethod})
  }
  await loadAll();updateDispatchModal(txid);if($('#dispatchScanInput'))$('#dispatchScanInput').focus()
}

function renderMovementAudit(){if(!isMovementAuditManager()){state.view='dispatch';return renderDispatch()}head('Equipment Movement Audit','Separate tamper-resistant record of who checked equipment OUT and IN for each event.');let rows=bData('movementAudit');rows=sortByDateDesc(rows,'created_at');$('#viewRoot').innerHTML=`<div class="panel"><div class="panel-head"><div><h2>Equipment Movement Audit</h2><p class="muted">Generated automatically by the database whenever equipment status changes to OUT or RETURNED. Staff cannot edit or delete these records.</p></div><button class="btn" id="refreshMovementAudit">Refresh</button></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Date / Time</th><th>Action</th><th>Qty</th><th>User</th><th>Event</th><th>Equipment</th><th>Asset Code</th><th>Scan Method</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(new Date(x.created_at).toLocaleString())}</td><td><span class="badge ${x.action==='OUT'?'repair':'ready'}">${esc(x.action||'')}</span></td><td><strong>${Number(x.quantity||1)}</strong></td><td><strong>${esc(x.user_name||x.user_email||'Unknown User')}</strong><br><small>${esc(x.user_email||'')}</small></td><td>${esc(x.event_date||'')}<br><small>${esc(x.client_name||'')} ${x.venue?'• '+esc(x.venue):''}</small></td><td><strong>${esc(x.equipment_name||'')}</strong></td><td><code>${esc(x.asset_code||'')}</code></td><td>${esc(x.scan_method||'')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No equipment movement records yet.</div>'}</div>`;$('#refreshMovementAudit').onclick=async()=>{await loadAll();renderMovementAudit();toast('Equipment movement audit refreshed.')}}
