async function deletePayment(id){const x=state.data.payments.find(v=>v.id===id);const {error}=await sb.from('payments').delete().eq('id',id);if(error)return toast(error.message,'error');await audit('DELETE','payments',id,{transaction_id:x?.transaction_id||null,amount:x?.amount||0});toast('Payment deleted.');await loadAll();render()}
function renderExpenses(){
  head('Expenses','Event expenses grouped by event/client, with standalone and repair expenses shown at the bottom.');
  const all=bData('expenses');
  let rows=dateFilterRows(all,'expense_date','expenses');
  rows=searchRows(rows,'expenses',r=>{
    const t=state.data.transactions.find(x=>x.id===r.transaction_id);
    return `${t?.client_name_snapshot||''} ${t?.item_name_snapshot||''} ${transactionCategoryName(t)||''} ${r.category||''} ${r.remarks||r.description||''}`;
  });
  rows=sortByDateDesc(rows,'expense_date');
  const total=rows.reduce((s,x)=>s+Number(x.amount||0),0);

  if(state.business==='njs'){
    const bookingRows=rows.filter(x=>x.transaction_id);
    const standaloneRows=rows.filter(x=>!x.transaction_id);
    const groups=new Map();

    for(const x of bookingRows){
      if(!groups.has(x.transaction_id))groups.set(x.transaction_id,[]);
      groups.get(x.transaction_id).push(x);
    }

    const bookingGroups=[...groups.entries()].map(([txId,g])=>{
      const t=state.data.transactions.find(v=>v.id===txId);
      const gt=g.reduce((s,x)=>s+Number(x.amount||0),0);
      const eventTitle=(t?.event_name||t?.booking_name||t?.client_name_snapshot||'Booking').trim();
      const category=transactionCategoryName(t);
      const subtitle=[category,t?.event_date].filter(Boolean).join(' • ');
      return {t,g,gt,eventTitle,subtitle};
    }).sort((a,b)=>String(b.t?.event_date||'').localeCompare(String(a.t?.event_date||'')));

    const standaloneTotal=standaloneRows.reduce((s,x)=>s+Number(x.amount||0),0);

    $('#viewRoot').innerHTML=`
      <div class="grid cards"><div class="card"><div class="label">Total Expenses</div><div class="value">${money(total)}</div></div></div>
      <div class="panel">
        <div class="panel-head"><div><h2>Expenses by Booking / Event</h2><p class="muted">Grouped booking expenses are shown first. Standalone and repair expenses are listed at the bottom.</p></div><div class="toolbar">${searchHtml('expenses','Search booking, client, category or remarks...')}${dateFilterHtml(all,'expense_date','expenses')}<button class="btn primary" id="addExpense">+ Add Expense</button></div></div>
        ${bookingGroups.length?bookingGroups.map(({t,g,gt,eventTitle,subtitle})=>`<div class="expense-group"><div class="panel-head"><div><h3>${esc(eventTitle)}</h3><p class="muted">${esc(subtitle||'Booking Expense')}${t?.item_name_snapshot?` • Package: ${esc(t.item_name_snapshot)}`:''}</p></div><strong>${money(gt)}</strong></div><div class="table-wrap"><table><thead><tr><th>Category</th><th>Amount</th><th>Remarks</th><th>Actions</th></tr></thead><tbody>${g.map(x=>`<tr><td>${esc(x.category||'')}</td><td>${money(x.amount)}</td><td>${esc(x.remarks||x.description||'')}</td><td><button class="btn small" data-editexpense="${x.id}">Edit</button> <button class="btn small" data-payexpense="${x.id}">Payment</button></td></tr>`).join('')}</tbody></table></div></div>`).join(''):'<div class="empty">No booking/event expenses match the selected filters.</div>'}

        <div class="expense-standalone-section" style="margin-top:28px;padding-top:24px;border-top:2px solid var(--line,#e5e7eb)">
          <div class="panel-head"><div><h2>Standalone / Repair Expenses</h2><p class="muted">Expenses not linked to a booking or event.</p></div><strong>${money(standaloneTotal)}</strong></div>
          ${standaloneRows.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Category</th><th>Amount</th><th>Remarks</th><th>Actions</th></tr></thead><tbody>${standaloneRows.map(x=>`<tr><td>${esc(x.expense_date||'')}</td><td>${esc(x.category||'')}</td><td>${money(x.amount)}</td><td>${esc(x.remarks||x.description||'')}</td><td><button class="btn small" data-editexpense="${x.id}">Edit</button> <button class="btn small" data-payexpense="${x.id}">Payment</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No standalone or repair expenses.</div>'}
        </div>
      </div>`;
  }else{
    $('#viewRoot').innerHTML=`<div class="grid cards"><div class="card"><div class="label">Total Expenses</div><div class="value">${money(total)}</div></div></div><div class="panel"><div class="panel-head"><h2>Expenses</h2><div class="toolbar">${searchHtml('expenses','Search expenses...')}${dateFilterHtml(all,'expense_date','expenses')}<button class="btn primary" id="addExpense">+ Add Expense</button></div></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Category</th><th>Amount</th><th>Remarks</th><th>Actions</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.expense_date)}</td><td>${esc(x.category||'')}</td><td>${money(x.amount)}</td><td>${esc(x.remarks||'')}</td><td><button class="btn small" data-editexpense="${x.id}">Edit</button> <button class="btn small" data-payexpense="${x.id}">Payment</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No expenses.</div>'}</div>`;
  }
  bindDateFilter('expenses',renderExpenses);
  bindSearch('expenses',renderExpenses);
  $('#addExpense').onclick=()=>expenseForm();
  $$('[data-editexpense]').forEach(b=>b.onclick=()=>expenseForm(b.dataset.editexpense));
  $$('[data-payexpense]').forEach(b=>b.onclick=()=>paymentForm(null,{expenseId:b.dataset.payexpense}));
}

function expenseForm(id=null){const x=state.data.expenses.find(v=>v.id===id)||{};if(x.repair_record_id)return repairForm(x.repair_record_id);modal(`${id?'Edit':'Add'} Expense`,`<form id="expenseForm" class="form-grid"><label>Date<input id="expDate" type="date" value="${esc(x.expense_date||new Date().toISOString().slice(0,10))}" required></label><label>Category<input id="expCategory" value="${esc(x.category||'')}" list="expenseCategoryList" required><datalist id="expenseCategoryList"><option>Transportation</option><option>Cables & Consumables</option><option>Equipment Rental</option><option>Crew / Labor</option><option>Staff</option><option>Food</option><option>Repair & Maintenance</option><option>Utilities</option><option>Lights & Sound Consumables</option><option>Miscellaneous</option></datalist></label><label>Amount<input id="expAmount" type="number" min="0" step="0.01" value="${Number(x.amount||0)}" required></label><label>Linked ${txLabel()}<select id="expTx"><option value="">None / Standalone</option>${bData('transactions').map(t=>`<option value="${t.id}" ${x.transaction_id===t.id?'selected':''}>${esc(t.event_date)} — ${esc(t.client_name_snapshot||'Client')}</option>`).join('')}</select></label><label class="full">Remarks<textarea id="expRemarks">${esc(x.remarks||x.description||'')}</textarea></label><div class="form-actions full"><button type="button" class="btn" data-close>Cancel</button><button class="btn primary">Save Expense</button></div></form>`);$('#expenseForm').onsubmit=async e=>{e.preventDefault();const row={business_code:state.business,transaction_id:$('#expTx').value||null,repair_record_id:null,category:$('#expCategory').value.trim(),description:$('#expRemarks').value.trim()||null,remarks:$('#expRemarks').value.trim()||null,amount:Number($('#expAmount').value||0),expense_date:$('#expDate').value,created_by:state.user.id};const {data,error}=await(id?sb.from('expenses').update(row).eq('id',id).select().maybeSingle():sb.from('expenses').insert(row).select().maybeSingle());if(error)return toast(error.message,'error');await audit(id?'UPDATE':'CREATE','expenses',id||(data&&data.id)||'',row);toast(`Expense ${id?'updated':'added'}.`);closeModal();await loadAll();render()}}
async function deleteExpense(id){const x=state.data.expenses.find(v=>v.id===id);if(x?.repair_record_id)return toast('This is a repair expense. Delete the repair record instead so all linked data stays consistent.','warning');const {error}=await sb.from('expenses').delete().eq('id',id);if(error)return toast(error.message,'error');await audit('DELETE','expenses',id,{amount:x?.amount||0,category:x?.category||''});toast('Expense and linked expense payments deleted.');await loadAll();render()}
function renderPos(){head('Mini POS','Counter sales, consumables, accessories and professional sales invoices.');let products=state.data.posProducts.filter(x=>x.business_code==='njs'&&x.active!==false).sort((a,b)=>alpha(a.name,b.name));products=searchRows(products,'posProducts');let sales=dateFilterRows(state.data.posSales.filter(x=>x.business_code==='njs'),'sale_date','pos');sales=searchRows(sales,'posSales');$('#viewRoot').innerHTML=`<div class="grid cards"><div class="card"><div class="label">Active POS Products</div><div class="value">${products.length}</div></div><div class="card"><div class="label">Stock Value</div><div class="value">${money(products.reduce((s,p)=>s+Number(p.quantity_on_hand||0)*Number(p.cost_price||0),0))}</div></div><div class="card"><div class="label">Sales</div><div class="value">${money(sales.reduce((s,x)=>s+Number(x.total_amount||0),0))}</div></div></div><div class="panel"><div class="panel-head"><h2>POS Products / Sale Items</h2><div class="toolbar">${searchHtml('posProducts','Search products...')}<button class="btn primary" id="addProduct">+ Add Product</button></div></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>Qty</th><th>Sell Price</th><th>Expiration</th><th>Remarks</th><th>Actions</th></tr></thead><tbody>${products.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.category||'')}</td><td>${Number(p.quantity_on_hand||0)}</td><td>${money(p.selling_price)}</td><td>${esc(p.expiration_date||'—')}</td><td>${esc(p.remarks||'')}</td><td><button class="btn small" data-editproduct="${p.id}">Edit</button> <button class="btn small danger" data-delproduct="${p.id}">Delete</button></td></tr>`).join('')}</tbody></table></div></div><div class="panel"><div class="panel-head"><h2>Sales</h2><div class="toolbar">${searchHtml('posSales','Search buyer/date...')}${dateFilterHtml(state.data.posSales,'sale_date','pos')}<button class="btn primary" id="addSale">+ New Sale</button></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Buyer</th><th>Total</th><th>Payment</th><th>Remarks</th><th>Actions</th></tr></thead><tbody>${sales.map(x=>`<tr><td>${esc(x.sale_date)}</td><td>${esc(x.buyer_name||'Walk-in')}</td><td>${money(x.total_amount)}</td><td>${esc(x.payment_method||'')}</td><td>${esc(x.remarks||'')}</td><td><button class="btn small" data-viewsale="${x.id}">View</button> <button class="btn small" data-invoicesale="${x.id}">Invoice</button> <button class="btn small" data-editsale="${x.id}">Edit</button> <button class="btn small danger" data-delsale="${x.id}">Delete</button></td></tr>`).join('')}</tbody></table></div></div>`;bindSearch('posProducts',renderPos);bindSearch('posSales',renderPos);bindDateFilter('pos',renderPos);$('#addProduct').onclick=()=>productForm();$('#addSale').onclick=()=>saleForm();$$('[data-editproduct]').forEach(b=>b.onclick=()=>productForm(b.dataset.editproduct));$$('[data-delproduct]').forEach(b=>b.onclick=()=>confirmModal('Delete Product','Delete this product?',()=>deleteProduct(b.dataset.delproduct)));$$('[data-viewsale]').forEach(b=>b.onclick=()=>viewPosSale(b.dataset.viewsale));$$('[data-invoicesale]').forEach(b=>b.onclick=()=>printPosInvoice(b.dataset.invoicesale));$$('[data-editsale]').forEach(b=>b.onclick=()=>saleForm(b.dataset.editsale));$$('[data-delsale]').forEach(b=>b.onclick=()=>confirmModal('Delete Sale','Delete this sale and restore stock?',()=>deleteSale(b.dataset.delsale)))}
function productForm(id=null){const x=state.data.posProducts.find(p=>p.id===id)||{};modal(`${id?'Edit':'Add'} Product`,`<form id="productForm" class="form-grid"><label>Name<input id="prodName" value="${esc(x.name||'')}" required></label><label>Category<input id="prodCat" value="${esc(x.category||'')}"></label><label>Cost Price<input id="prodCost" type="number" min="0" step="0.01" value="${Number(x.cost_price||0)}"></label><label>Selling Price<input id="prodSell" type="number" min="0" step="0.01" value="${Number(x.selling_price||0)}"></label><label>Quantity<input id="prodQty" type="number" min="0" step="1" value="${Number(x.quantity_on_hand||0)}"></label><label>Expiration<input id="prodExp" type="date" value="${esc(x.expiration_date||'')}"></label><label class="full">Remarks<textarea id="prodRemarks">${esc(x.remarks||'')}</textarea></label><div class="form-actions full"><button type="button" class="btn" data-close>Cancel</button><button class="btn primary">Save</button></div></form>`);$('#productForm').onsubmit=async e=>{e.preventDefault();const row={business_code:'njs',name:$('#prodName').value.trim(),category:$('#prodCat').value.trim()||null,cost_price:Number($('#prodCost').value||0),selling_price:Number($('#prodSell').value||0),quantity_on_hand:Number($('#prodQty').value||0),expiration_date:$('#prodExp').value||null,remarks:$('#prodRemarks').value.trim()||null,active:true,created_by:state.user.id};const {data,error}=await(id?sb.from('pos_products').update(row).eq('id',id).select().single():sb.from('pos_products').insert(row).select().single());if(error)return toast(error.message,'error');await audit(id?'UPDATE':'CREATE','pos_products',id||data.id,row);closeModal();await loadAll();renderPos()}}
function saleRowHtml(r={}){return `<div class="line-row pos-sale-row"><select class="sale-product"><option value="">Product</option>${state.data.posProducts.filter(p=>p.active!==false).map(p=>`<option value="${p.id}" data-price="${p.selling_price}" ${r.product_id===p.id?'selected':''}>${esc(p.name)} (Stock ${Number(p.quantity_on_hand||0)})</option>`).join('')}</select><input class="sale-qty" type="number" min="1" step="1" value="${Number(r.quantity||1)}"><input class="sale-price locked-input" readonly value="${Number(r.unit_price||0)}"><button type="button" class="btn small danger remove-line">×</button></div>`}
function saleForm(id=null){
  const x=state.data.posSales.find(v=>v.id===id)||{};
  const oldItems=state.data.posSaleItems.filter(i=>i.sale_id===id);
  modal(`${id?'Edit':'New'} Sale`,`<form id="saleForm"><div class="form-grid"><label>Client<select id="saleClient"><option value="">Walk-in / Other</option>${clientOptions(x.client_id)}</select></label><label>Buyer Name<input id="saleBuyer" value="${esc(x.buyer_name||'')}"></label><label>Date<input id="saleDate" type="date" value="${esc(x.sale_date||new Date().toISOString().slice(0,10))}"></label><label>Payment Method<select id="saleMethod">${['Cash','GCash','Maya','Bank Transfer','Other'].map(m=>`<option ${x.payment_method===m?'selected':''}>${m}</option>`).join('')}</select></label><label class="full">Remarks<textarea id="saleRemarks">${esc(x.remarks||'')}</textarea></label></div><h3>Items</h3><div id="saleRows">${oldItems.length?oldItems.map(saleRowHtml).join(''):saleRowHtml()}</div><button type="button" class="btn" id="addSaleRow">+ Add Item</button><div class="summary-box"><small>Total</small><strong id="saleTotal">₱0.00</strong></div><div class="form-actions"><button type="button" class="btn" data-close>Cancel</button><button class="btn primary">Save Sale</button></div></form>`,{wide:true});
  const calc=()=>{$('#saleTotal').textContent=money($$('.pos-sale-row').reduce((sum,row)=>sum+Number($('.sale-qty',row).value||0)*Number($('.sale-price',row).value||0),0))};
  const bind=()=>{$$('.sale-product').forEach(sel=>sel.onchange=()=>{const row=sel.closest('.pos-sale-row');$('.sale-price',row).value=Number(sel.selectedOptions[0]?.dataset.price||0);calc()});$$('.sale-qty').forEach(input=>input.oninput=calc);$$('.remove-line').forEach(btn=>btn.onclick=()=>{btn.closest('.pos-sale-row').remove();calc()})};
  $('#addSaleRow').onclick=()=>{$('#saleRows').insertAdjacentHTML('beforeend',saleRowHtml());bind();calc()};bind();calc();
  $('#saleForm').onsubmit=async e=>{
    e.preventDefault();
    const rows=$$('.pos-sale-row').map(row=>({product_id:$('.sale-product',row).value,quantity:Number($('.sale-qty',row).value||0),unit_price:Number($('.sale-price',row).value||0)})).filter(r=>r.product_id&&r.quantity>0);
    if(!rows.length)return toast('Add at least one product.','warning');
    const restored={};oldItems.forEach(i=>restored[i.product_id]=(restored[i.product_id]||0)+Number(i.quantity||0));
    for(const r of rows){const prod=state.data.posProducts.find(p=>p.id===r.product_id),available=Number(prod?.quantity_on_hand||0)+(id?(restored[r.product_id]||0):0);if(r.quantity>available)return toast(`Insufficient stock for ${prod?.name||'product'}.`,'error')}
    if(id){for(const old of oldItems){const prod=state.data.posProducts.find(p=>p.id===old.product_id);if(prod){const restoredQty=Number(prod.quantity_on_hand||0)+(restored[prod.id]||0);await sb.from('pos_products').update({quantity_on_hand:restoredQty}).eq('id',prod.id)}}const {error}=await sb.from('pos_sale_items').delete().eq('sale_id',id);if(error)return toast(error.message,'error')}
    const client=state.data.clients.find(c=>c.id===$('#saleClient').value);const total=rows.reduce((sum,r)=>sum+r.quantity*r.unit_price,0);const sale={business_code:'njs',client_id:client?.id||null,buyer_name:$('#saleBuyer').value.trim()||client?.name||'Walk-in',sale_date:$('#saleDate').value,payment_method:$('#saleMethod').value,total_amount:total,remarks:$('#saleRemarks').value.trim()||null,created_by:state.user.id};
    let saleId=id;if(id){const {error}=await sb.from('pos_sales').update(sale).eq('id',id);if(error)return toast(error.message,'error')}else{const {data,error}=await sb.from('pos_sales').insert(sale).select().single();if(error)return toast(error.message,'error');saleId=data.id}
    const itemRows=rows.map(r=>({sale_id:saleId,product_id:r.product_id,product_name_snapshot:state.data.posProducts.find(p=>p.id===r.product_id)?.name||'Product',quantity:r.quantity,unit_price:r.unit_price}));const {error:itemErr}=await sb.from('pos_sale_items').insert(itemRows);if(itemErr)return toast(itemErr.message,'error');
    for(const r of rows){const prod=state.data.posProducts.find(p=>p.id===r.product_id);const base=Number(prod?.quantity_on_hand||0)+(id?(restored[r.product_id]||0):0);const {error}=await sb.from('pos_products').update({quantity_on_hand:base-r.quantity}).eq('id',r.product_id);if(error)return toast(error.message,'error')}
    await audit(id?'UPDATE':'CREATE','pos_sales',saleId,{buyer:sale.buyer_name,total,items:rows.length});toast('POS sale saved.');closeModal();await loadAll();renderPos();
  };
}
async function deleteProduct(id){const used=state.data.posSaleItems.some(i=>i.product_id===id);if(used){await sb.from('pos_products').update({active:false}).eq('id',id);await audit('ARCHIVE','pos_products',id);toast('Product has sales history and was marked inactive.')}else{await sb.from('pos_products').delete().eq('id',id);await audit('DELETE','pos_products',id)}await loadAll();renderPos()}
async function deleteSale(id){const items=state.data.posSaleItems.filter(i=>i.sale_id===id);for(const i of items){const p=state.data.posProducts.find(x=>x.id===i.product_id);if(p)await sb.from('pos_products').update({quantity_on_hand:Number(p.quantity_on_hand||0)+Number(i.quantity||0)}).eq('id',p.id)}await sb.from('pos_sales').delete().eq('id',id);await audit('DELETE','pos_sales',id,{stock_restored:true});await loadAll();renderPos()}
function posInvoiceNumber(sale){const d=String(sale?.sale_date||new Date().toISOString().slice(0,10)).replaceAll('-','');const suffix=String(sale?.id||'SALE').replaceAll('-','').slice(0,8).toUpperCase();return `POS-${d}-${suffix}`}
function posSaleItemsFor(saleId){return state.data.posSaleItems.filter(i=>i.sale_id===saleId)}
function viewPosSale(id){
  const sale=state.data.posSales.find(x=>x.id===id);if(!sale)return toast('POS sale not found.','error');
  const items=posSaleItemsFor(id);const client=state.data.clients.find(c=>c.id===sale.client_id);const invoiceNo=posInvoiceNumber(sale);const logo=logoAssetUrl();
  const rows=items.length?items.map(i=>`<tr><td>${esc(i.product_name_snapshot||state.data.posProducts.find(p=>p.id===i.product_id)?.name||'Product')}</td><td>${Number(i.quantity||0)}</td><td>${money(i.unit_price)}</td><td>${money(Number(i.quantity||0)*Number(i.unit_price||0))}</td></tr>`).join(''):`<tr><td colspan="4" class="muted">No sale items found.</td></tr>`;
  modal('POS Sale / Receipt',`<div class="summary-grid"><div class="summary-box"><small>Invoice No.</small><strong>${esc(invoiceNo)}</strong></div><div class="summary-box"><small>Buyer</small><strong>${esc(sale.buyer_name||client?.name||'Walk-in')}</strong></div><div class="summary-box"><small>Date</small><strong>${esc(sale.sale_date||'')}</strong></div><div class="summary-box"><small>Total</small><strong>${money(sale.total_amount)}</strong></div></div><h3 class="section-title">Sale Items</h3><div class="table-wrap"><table><thead><tr><th>Product</th><th>Qty</th><th>Unit Price</th><th>Line Total</th></tr></thead><tbody>${rows}</tbody></table></div><h3 class="section-title">Payment Details</h3><div class="table-wrap"><table><tbody><tr><th>Payment Method</th><td>${esc(sale.payment_method||'')}</td><th>Client Record</th><td>${esc(client?.name||'Walk-in / Other')}</td></tr><tr><th>Remarks</th><td colspan="3">${esc(sale.remarks||'—')}</td></tr></tbody></table></div><div class="form-actions"><button class="btn" data-close>Close</button><button class="btn primary" id="printPosInvoiceBtn">Print Invoice</button></div>`,{wide:true});
  $('#printPosInvoiceBtn').onclick=()=>printPosInvoice(id);
}
function printPosInvoice(id){
  const sale=state.data.posSales.find(x=>x.id===id);if(!sale)return toast('POS sale not found.','error');
  const items=posSaleItemsFor(id);const client=state.data.clients.find(c=>c.id===sale.client_id);const invoiceNo=posInvoiceNumber(sale);const logo=logoAssetUrl();
  const itemRows=items.map(i=>`<tr><td>${esc(i.product_name_snapshot||state.data.posProducts.find(p=>p.id===i.product_id)?.name||'Product')}</td><td>${Number(i.quantity||0)}</td><td>${money(i.unit_price)}</td><td>${money(Number(i.quantity||0)*Number(i.unit_price||0))}</td></tr>`).join('');
  const html=`<!doctype html><html><head><meta charset="utf-8"><title>${esc(invoiceNo)}</title><style>body{font-family:Arial,sans-serif;color:#171717;margin:0;padding:28px;background:#fff}.invoice{max-width:820px;margin:auto}.head{display:flex;justify-content:space-between;align-items:flex-start;gap:24px;border-bottom:3px solid #d92d20;padding-bottom:16px}.invoice-logo{display:flex;align-items:center}.invoice-logo img{width:110px;height:110px;object-fit:contain;display:block}.brand{text-align:right}.brand h1{margin:0;font-size:24px}.brand .type{font-weight:700;letter-spacing:.08em;color:#d92d20}.muted{color:#667085}.details{display:grid;grid-template-columns:1fr 1fr;gap:10px 26px;margin:22px 0}.section{margin:22px 0}.section h3{font-size:14px;text-transform:uppercase;letter-spacing:.06em;border-bottom:1px solid #ddd;padding-bottom:7px}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #e5e7eb;text-align:left;font-size:13px}th{background:#f8fafc}.num{text-align:right}.total{margin-left:auto;width:min(360px,100%);margin-top:14px}.total td:last-child{text-align:right;font-size:18px;font-weight:800}.footer{margin-top:34px;text-align:center;color:#667085;font-size:12px}@media print{body{padding:0}}</style></head><body><div class="invoice"><div class="head"><div class="invoice-logo"><img src="${logo}" alt="NJ logo"></div><div class="brand"><h1>${esc(businessName())}</h1><div class="type">POS SALES INVOICE</div><div class="muted">Invoice # ${esc(invoiceNo)}</div><div class="muted">${esc(sale.sale_date||'')}</div></div></div><div class="details"><div><strong>Buyer</strong><br>${esc(sale.buyer_name||client?.name||'Walk-in')}<br>${client?.contact?esc(client.contact):''}</div><div><strong>Payment Method</strong><br>${esc(sale.payment_method||'')}</div></div><div class="section"><h3>Products</h3><table><thead><tr><th>Product</th><th>Qty</th><th>Unit Price</th><th>Amount</th></tr></thead><tbody>${itemRows||'<tr><td colspan="4">No items found.</td></tr>'}</tbody></table><table class="total"><tr><td>Grand Total</td><td>${money(sale.total_amount)}</td></tr></table></div>${sale.remarks?`<div class="section"><h3>Remarks</h3><div>${esc(sale.remarks)}</div></div>`:''}<div class="footer">Thank you for your purchase from ${esc(businessName())}.</div></div></body></html>`;
  const oldFrame=document.getElementById('posInvoicePrintFrame');if(oldFrame)oldFrame.remove();const frame=document.createElement('iframe');frame.id='posInvoicePrintFrame';frame.style.position='fixed';frame.style.right='0';frame.style.bottom='0';frame.style.width='0';frame.style.height='0';frame.style.border='0';frame.style.visibility='hidden';document.body.appendChild(frame);const doc=frame.contentWindow.document;doc.open();doc.write(html);doc.close();frame.onload=()=>{setTimeout(()=>{frame.contentWindow.focus();frame.contentWindow.print();setTimeout(()=>frame.remove(),1200)},250)};audit('PRINT_POS_INVOICE','pos_sales',sale.id,{invoice_no:invoiceNo,total:sale.total_amount,buyer:sale.buyer_name||'Walk-in'});
}
