function exportScopeData(){
  const map={clients:'clients',categories:'catalog_categories',catalog:'catalog_items',libraryCategories:'library_categories',library:'library_items',links:'catalog_library_links',inventoryCategories:'inventory_categories',equipmentTypes:'equipment_types',inventory:'inventory_items',transactionCategories:'transaction_categories',transactionLibraryLinks:'transaction_library_links',catalogInventoryLinks:'catalog_inventory_links',catalogTypeRequirements:'catalog_equipment_type_requirements',transactionTypeRequirements:'transaction_equipment_type_requirements',transactions:'transactions',charges:'transaction_additional_charges',coupons:'coupons',transactionAddons:'transaction_inventory_addons',transactionPackageAddons:'transaction_package_addons',payments:'payments',expenses:'expenses',repairs:'repair_records',checklist:'transaction_checklist',posProducts:'pos_products',posSales:'pos_sales',posSaleItems:'pos_sale_items',movementAudit:'equipment_movement_logs',audit:'audit_logs'};
  const out={};
  const business=state.business;
  for(const [keyName,table] of Object.entries(map)){
    let rows=[...(state.data[keyName]||[])];
    if(business!=='owner'){
      if(rows.some(r=>Object.prototype.hasOwnProperty.call(r,'business_code'))) rows=rows.filter(r=>r.business_code===business);
      else if(['catalog_library_links','transaction_library_links','catalog_inventory_links','catalog_equipment_type_requirements','transaction_equipment_type_requirements','transaction_checklist','pos_sale_items'].includes(table)){
        if(table==='catalog_library_links') rows=rows.filter(r=>state.data.catalog.some(c=>c.id===r.catalog_item_id&&c.business_code===business));
        if(table==='transaction_library_links') rows=rows.filter(r=>state.data.transactions.some(t=>t.id===r.transaction_id&&t.business_code===business));
        if(table==='catalog_inventory_links') rows=rows.filter(r=>state.data.catalog.some(c=>c.id===r.catalog_item_id&&c.business_code===business));
        if(table==='transaction_checklist') rows=rows.filter(r=>state.data.transactions.some(t=>t.id===r.transaction_id&&t.business_code===business));
        if(table==='pos_sale_items') rows=rows.filter(r=>state.data.posSales.some(s=>s.id===r.sale_id&&s.business_code===business));
      }
    }
    out[table]=rows;
  }
  return out;
}
