function validateUuid(v){return !v||/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(v)}
async function validateImport(file){
  pendingImport=null;
  let obj;
  try{obj=JSON.parse(await file.text())}catch(e){return showValidation(false,['Invalid JSON format.'],[],null)}
  const errs=[],warns=[];
  const known=['clients','catalog_categories','catalog_items','library_categories','library_items','catalog_library_links','inventory_categories','equipment_types','inventory_items','transaction_categories','transaction_library_links','catalog_inventory_links','catalog_equipment_type_requirements','transaction_equipment_type_requirements','transactions','transaction_additional_charges','coupons','transaction_inventory_addons','transaction_package_addons','payments','expenses','repair_records','transaction_checklist','pos_products','pos_sales','pos_sale_items'];
  if(obj.app!==C.APP_ID)errs.push('Wrong application identifier.');
  if(!obj.backup_version)errs.push('Missing backup version.');else if(Number(obj.schema_version||0)<6.5)warns.push('This is an older backup. Some newer event-management fields may be absent; existing database records will be preserved.');
  if(!obj.data||typeof obj.data!=='object'||Array.isArray(obj.data))errs.push('Missing or invalid data object.');
  if(obj.data&&typeof obj.data==='object'&&!Array.isArray(obj.data)){
    for(const [k,v] of Object.entries(obj.data)){
      if(!known.includes(k))warns.push(`Unknown section "${k}" will be ignored.`);
      if(known.includes(k)&&!Array.isArray(v))errs.push(`${k} must be an array.`);
    }
    for(const k of known){
      if(!(k in obj.data))warns.push(`${k} is not included; existing database records in that table will remain unchanged.`);
      const rows=Array.isArray(obj.data[k])?obj.data[k]:[];
      const ids=new Set();
      rows.forEach((r,idx)=>{
        if(!r||typeof r!=='object'||Array.isArray(r)){errs.push(`${k}[${idx}] is not a record object.`);return}
        if(r.id){if(!validateUuid(r.id))errs.push(`${k}[${idx}] has invalid id.`);if(ids.has(r.id))errs.push(`${k} contains duplicate id ${r.id}.`);ids.add(r.id)}
        if(r.business_code&&!['njs','salon'].includes(r.business_code))errs.push(`${k}[${idx}] has invalid business_code.`);
        ['price','amount','base_amount','discount_amount','additional_charges','labor_cost','parts_cost','transport_cost','other_cost','quantity','total_quantity','assigned_quantity','out_quantity','returned_quantity','damaged_quantity','missing_quantity','total_print','duration_hours','cost_price','selling_price','quantity_on_hand','unit_price','line_total','total_amount'].forEach(num=>{if(r[num]!=null&&(Number.isNaN(Number(r[num]))||Number(r[num])<0))errs.push(`${k}[${idx}].${num} must be a non-negative number.`)})
      });
    }
    const imported={catalog:new Set((obj.data.catalog_items||[]).map(r=>r.id)),library:new Set((obj.data.library_items||[]).map(r=>r.id)),inventory:new Set((obj.data.inventory_items||[]).map(r=>r.id)),transactions:new Set((obj.data.transactions||[]).map(r=>r.id)),expenses:new Set((obj.data.expenses||[]).map(r=>r.id)),repairs:new Set((obj.data.repair_records||[]).map(r=>r.id)),clients:new Set((obj.data.clients||[]).map(r=>r.id)),posProducts:new Set((obj.data.pos_products||[]).map(r=>r.id)),posSales:new Set((obj.data.pos_sales||[]).map(r=>r.id))};
    const current={catalog:new Set(state.data.catalog.map(r=>r.id)),library:new Set(state.data.library.map(r=>r.id)),inventory:new Set(state.data.inventory.map(r=>r.id)),transactions:new Set(state.data.transactions.map(r=>r.id)),expenses:new Set(state.data.expenses.map(r=>r.id)),repairs:new Set(state.data.repairs.map(r=>r.id)),clients:new Set(state.data.clients.map(r=>r.id)),posProducts:new Set(state.data.posProducts.map(r=>r.id)),posSales:new Set(state.data.posSales.map(r=>r.id))};
    const exists=(type,id)=>!id||imported[type].has(id)||current[type].has(id);
    (obj.data.catalog_library_links||[]).forEach(r=>{if(!exists('catalog',r.catalog_item_id))errs.push(`Catalog-library link references missing catalog_item_id ${r.catalog_item_id}.`);if(!exists('library',r.library_item_id))errs.push(`Catalog-library link references missing library_item_id ${r.library_item_id}.`)});
    (obj.data.transaction_library_links||[]).forEach(r=>{if(!exists('transactions',r.transaction_id))errs.push(`Transaction-library link references missing transaction_id ${r.transaction_id}.`);if(!exists('library',r.library_item_id))errs.push(`Transaction-library link references missing library_item_id ${r.library_item_id}.`)});
    (obj.data.catalog_inventory_links||[]).forEach(r=>{if(!exists('catalog',r.catalog_item_id))errs.push(`Catalog-equipment link references missing catalog_item_id ${r.catalog_item_id}.`);if(!exists('inventory',r.inventory_item_id))errs.push(`Catalog-equipment link references missing inventory_item_id ${r.inventory_item_id}.`)});
    (obj.data.transaction_checklist||[]).forEach(r=>{if(!exists('transactions',r.transaction_id))errs.push(`Checklist references missing transaction_id ${r.transaction_id}.`);if(!exists('inventory',r.inventory_item_id))errs.push(`Checklist references missing inventory_item_id ${r.inventory_item_id}.`)});
    (obj.data.payments||[]).forEach(r=>{if(r.transaction_id&&!exists('transactions',r.transaction_id))errs.push(`Payment references missing transaction_id ${r.transaction_id}.`);if(r.expense_id&&!exists('expenses',r.expense_id))errs.push(`Payment references missing expense_id ${r.expense_id}.`);if(r.repair_record_id&&!exists('repairs',r.repair_record_id))errs.push(`Payment references missing repair_record_id ${r.repair_record_id}.`)});
    (obj.data.transactions||[]).forEach(r=>{if(r.printer_id&&!exists('inventory',r.printer_id))errs.push(`Transaction references missing printer_id ${r.printer_id}.`)});
    (obj.data.transaction_additional_charges||[]).forEach(r=>{if(r.transaction_id&&!exists('transactions',r.transaction_id))errs.push(`Additional service/charge references missing transaction_id ${r.transaction_id}.`);if(r.catalog_item_id&&!exists('catalog',r.catalog_item_id))errs.push(`Additional service references missing catalog_item_id ${r.catalog_item_id}.`)});

    (obj.data.transaction_package_addons||[]).forEach(r=>{if(r.transaction_id&&!exists('transactions',r.transaction_id))errs.push(`Additional package references missing transaction_id ${r.transaction_id}.`);if(r.catalog_item_id&&!exists('catalog',r.catalog_item_id))errs.push(`Additional package references missing catalog_item_id ${r.catalog_item_id}.`);});    (obj.data.pos_sales||[]).forEach(r=>{if(r.client_id&&!exists('clients',r.client_id))errs.push(`POS sale references missing client_id ${r.client_id}.`)});
    (obj.data.pos_sale_items||[]).forEach(r=>{if(!exists('posSales',r.sale_id))errs.push(`POS sale item references missing sale_id ${r.sale_id}.`);if(!exists('posProducts',r.product_id))errs.push(`POS sale item references missing product_id ${r.product_id}.`)});
  }
  if(Array.isArray(obj.data.audit_logs)&&obj.data.audit_logs.length)warns.push(`Audit archive contains ${obj.data.audit_logs.length} log record(s). These are preserved in the backup file but intentionally not re-imported into the live audit trail.`);
  const ok=errs.length===0;
  if(ok)pendingImport=obj;
  showValidation(ok,errs,warns,obj);
  audit('VALIDATE_IMPORT','backup','',{valid:ok,error_count:errs.length,warning_count:warns.length,file:file.name});
}
function showValidation(ok,errs,warns,obj){
  const counts=obj?.data?Object.entries(obj.data).filter(([,v])=>Array.isArray(v)).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${v.length}</td></tr>`).join(''):'';
  $('#validationResult').innerHTML=ok?`<div class="validation-status valid">✓ FILE VALID</div><p><strong>Version:</strong> ${esc(obj.backup_version)} &nbsp; <strong>Exported:</strong> ${esc(obj.exported_at||'Unknown')}</p>${warns.length?`<div class="warning-list"><strong>Warnings</strong><ul>${warns.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div>`:''}<div class="table-wrap mini-table"><table><thead><tr><th>Section</th><th>Records</th></tr></thead><tbody>${counts}</tbody></table></div><p class="muted">Safe Merge is ready. No database records will be deleted simply because they are absent from the backup.</p>`:`<div class="validation-status invalid">✕ FILE INVALID — IMPORT BLOCKED</div><ul>${errs.map(e=>`<li>${esc(e)}</li>`).join('')}</ul>${warns?.length?`<div class="warning-list"><strong>Warnings</strong><ul>${warns.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div>`:''}`;
  const btn=$('#importJson');if(btn)btn.disabled=!ok;
}
async function importValidatedBackup(){
  if(!pendingImport)return toast('Validate a backup file first.','warning');
  const d=pendingImport.data;
  const order=['catalog_categories','library_categories','inventory_categories','equipment_types','transaction_categories','clients','catalog_items','library_items','inventory_items','transactions','transaction_additional_charges','coupons','transaction_inventory_addons','transaction_package_addons','catalog_library_links','transaction_library_links','catalog_inventory_links','catalog_equipment_type_requirements','transaction_equipment_type_requirements','transaction_checklist','pos_products','pos_sales','pos_sale_items'];
  const generatedByTable={transactions:['total_amount'],repair_records:['total_cost'],pos_sale_items:['line_total']};
  const sanitize=(table,row)=>{const x={...row};for(const k of (generatedByTable[table]||[]))delete x[k];return x};
  const upsertRows=async(table,rows)=>{
    if(!rows.length)return {ok:true,count:0};
    for(let i=0;i<rows.length;i+=200){
      const chunk=rows.slice(i,i+200).map(r=>sanitize(table,r));
      const onConflict=table==='catalog_library_links'?'catalog_item_id,library_item_id':table==='transaction_library_links'?'transaction_id,library_item_id,link_type':table==='catalog_inventory_links'?'catalog_item_id,inventory_item_id':table==='catalog_equipment_type_requirements'?'catalog_item_id,equipment_type_id':table==='transaction_equipment_type_requirements'?'transaction_id,equipment_type_id':table==='transaction_checklist'?'transaction_id,inventory_item_id':table==='transaction_package_addons'?'transaction_id,catalog_item_id':'id';
      const {error}=await sb.from(table).upsert(chunk,{onConflict});
      if(error)return {ok:false,error};
    }
    return {ok:true,count:rows.length};
  };
  status('IMPORTING…');const result={};
  // Circular repair <-> expense links are imported in two safe passes.
  const repairRows=(Array.isArray(d.repair_records)?d.repair_records:[]).map(r=>({...r,expense_id:null}));
  const expenseRows=(Array.isArray(d.expenses)?d.expenses:[]).map(r=>({...r,repair_record_id:null}));
  for(const table of order){
    const rows=Array.isArray(d[table])?d[table]:[];
    const res=await upsertRows(table,rows);
    if(!res.ok){status('DATABASE CONNECTED','connected');toast(`Import stopped at ${table}: ${res.error.message}`,'error');await audit('IMPORT_FAILED','backup','',{table,error:res.error.message});return}
    result[table]=res.count;
  }
  let res=await upsertRows('repair_records',repairRows);
  if(!res.ok){status('DATABASE CONNECTED','connected');toast(`Import stopped at repair_records: ${res.error.message}`,'error');await audit('IMPORT_FAILED','backup','',{table:'repair_records',error:res.error.message});return}
  result.repair_records=res.count;
  res=await upsertRows('expenses',expenseRows);
  if(!res.ok){status('DATABASE CONNECTED','connected');toast(`Import stopped at expenses: ${res.error.message}`,'error');await audit('IMPORT_FAILED','backup','',{table:'expenses',error:res.error.message});return}
  result.expenses=res.count;
  // Restore the two-way repair/expense references after both sides exist.
  for(const r of (Array.isArray(d.repair_records)?d.repair_records:[])){if(r.id&&r.expense_id){const {error}=await sb.from('repair_records').update({expense_id:r.expense_id}).eq('id',r.id);if(error){status('DATABASE CONNECTED','connected');toast(`Import link restore failed: ${error.message}`,'error');await audit('IMPORT_FAILED','backup','',{table:'repair_records',stage:'restore_expense_link',error:error.message});return}}}
  for(const e of (Array.isArray(d.expenses)?d.expenses:[])){if(e.id&&e.repair_record_id){const {error}=await sb.from('expenses').update({repair_record_id:e.repair_record_id}).eq('id',e.id);if(error){status('DATABASE CONNECTED','connected');toast(`Import link restore failed: ${error.message}`,'error');await audit('IMPORT_FAILED','backup','',{table:'expenses',stage:'restore_repair_link',error:error.message});return}}}
  res=await upsertRows('payments',Array.isArray(d.payments)?d.payments:[]);
  if(!res.ok){status('DATABASE CONNECTED','connected');toast(`Import stopped at payments: ${res.error.message}`,'error');await audit('IMPORT_FAILED','backup','',{table:'payments',error:res.error.message});return}
  result.payments=res.count;
  await audit('IMPORT','backup','',{mode:'safe-merge',schema_version:6.5,counts:result});pendingImport=null;await loadAll();status('DATABASE CONNECTED','connected');renderBackup();toast('Validated backup imported successfully.');
}
async function runDatabaseHealthCheck(){
  const tables=['profiles','role_permissions','clients','catalog_categories','catalog_items','library_categories','library_items','catalog_library_links','inventory_categories','equipment_types','inventory_items','transaction_categories','transaction_library_links','catalog_inventory_links','catalog_equipment_type_requirements','transaction_equipment_type_requirements','transactions','transaction_additional_charges','coupons','transaction_inventory_addons','transaction_package_addons','payments','expenses','repair_records','transaction_checklist','equipment_movement_logs','pos_products','pos_sales','pos_sale_items','audit_logs'];
  const rows=[];for(const t of tables){const {count,error}=await sb.from(t).select('*',{count:'exact',head:true});rows.push({table:t,ok:!error,count:count??0,error:error?.message||''})}
  modal('Database Health Check',`<div class="summary-grid"><div class="summary-box"><small>Working Tables</small><strong>${rows.filter(r=>r.ok).length}</strong></div><div class="summary-box"><small>Errors</small><strong>${rows.filter(r=>!r.ok).length}</strong></div></div><div class="table-wrap"><table><thead><tr><th>Table</th><th>Status</th><th>Rows</th><th>Message</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.table)}</td><td><span class="badge ${r.ok?'good':'bad'}">${r.ok?'Connected':'Error'}</span></td><td>${r.ok?r.count:'—'}</td><td>${esc(r.error)}</td></tr>`).join('')}</tbody></table></div><div class="form-actions"><button class="btn" data-close>Close</button></div>`,{wide:true});
}
async function saveRolePermission(role,module,field,value){
  if(!requirePermission('access','edit'))return;
  const existing=state.data.rolePermissions.find(x=>x.role_name===role&&x.module===module);const row={role_name:role,module,can_view:existing?.can_view||false,can_add:existing?.can_add||false,can_edit:existing?.can_edit||false,can_delete:existing?.can_delete||false,[field]:value};
  const {error}=await sb.from('role_permissions').upsert(row,{onConflict:'role_name,module'});if(error)return toast(error.message,'error');await audit('UPDATE','roles',`${role}:${module}`,{field,value});await loadAll();renderAccess();toast('Role permission updated.');
}
async function saveUserAccess(id){
  if(!requirePermission('access','edit'))return;const role=$(`#userRole_${id}`)?.value,active=$(`#userActive_${id}`)?.value==='true';if(!role)return;
  const target=state.data.profiles.find(x=>x.id===id);if(target?.role==='owner'){toast('Owner account cannot be changed here.','warning');return}
  const {error}=await sb.from('profiles').update({role,active}).eq('id',id);if(error)return toast(error.message,'error');await audit('UPDATE','user_access',id,{email:target?.email,role,active});await loadAll();renderAccess();toast('User access updated.');
}
function renderAccess(){
  if(!requirePermission('access','view')){state.view='dashboard';return render()}
  head('Users & Roles','Owner-controlled staff roles and per-page permissions.');
  const roles=['administrator','staff','viewer'],users=[...(state.data.profiles||[])].sort((a,b)=>alpha(a.full_name||a.email,b.full_name||b.email));
  const matrix=roles.map(role=>`<div class="panel role-matrix-panel"><div class="panel-head"><div><h2>${esc(role.charAt(0).toUpperCase()+role.slice(1))}</h2><p class="muted">Changes are enforced by both the interface and Supabase RLS.</p></div></div><div class="table-wrap"><table class="permission-table"><thead><tr><th>Page / Module</th><th>View</th><th>Add</th><th>Edit / Update</th><th>Delete</th></tr></thead><tbody>${permissionModules.filter(x=>x[0]!=='access').map(([m,label])=>{const rp=state.data.rolePermissions.find(x=>x.role_name===role&&x.module===m);const vals=rp?[rp.can_view,rp.can_add,rp.can_edit,rp.can_delete]:(defaultPermissions[role]?.[m]||[0,0,0,0]);return `<tr><td><strong>${esc(label)}</strong></td>${['can_view','can_add','can_edit','can_delete'].map((f,i)=>`<td><input class="perm-check" type="checkbox" data-role="${role}" data-module="${m}" data-field="${f}" ${vals[i]?'checked':''}></td>`).join('')}</tr>`}).join('')}</tbody></table></div></div>`).join('');
  $('#viewRoot').innerHTML=`<div class="panel access-hero"><div><span class="eyebrow">OWNER CONTROL</span><h2>User Accounts & Access</h2><p class="muted">Public signup remains OFF. Create Auth users only from your Supabase Owner dashboard for now, then assign their system role here.</p></div></div><div class="panel"><div class="panel-head"><div><h2>System Users</h2><p class="muted">Owner is protected. Staff can be activated/deactivated and assigned a role.</p></div></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Action</th></tr></thead><tbody>${users.map(u=>{const owner=String(u.role).toLowerCase()==='owner';return `<tr><td>${esc(u.full_name||'—')}</td><td>${esc(u.email||'')}</td><td>${owner?'<span class="badge good">Owner</span>':`<select id="userRole_${u.id}"><option value="administrator" ${u.role==='administrator'?'selected':''}>Administrator</option><option value="staff" ${u.role==='staff'?'selected':''}>Staff</option><option value="viewer" ${u.role==='viewer'?'selected':''}>Viewer</option></select>`}</td><td>${owner?'<span class="badge good">Active</span>':`<select id="userActive_${u.id}"><option value="true" ${u.active!==false?'selected':''}>Active</option><option value="false" ${u.active===false?'selected':''}>Inactive</option></select>`}</td><td>${owner?'<span class="muted">Protected</span>':`<button class="btn small primary" data-saveuser="${u.id}">Save</button>`}</td></tr>`}).join('')}</tbody></table></div></div><div class="access-note"><strong>Owner:</strong> always has full access and cannot be limited by this matrix.</div>${matrix}`;
  $$('[data-saveuser]').forEach(b=>b.onclick=()=>saveUserAccess(b.dataset.saveuser));$$('.perm-check').forEach(c=>c.onchange=()=>saveRolePermission(c.dataset.role,c.dataset.module,c.dataset.field,c.checked));
}
function renderSettings(){
  head('Settings','System, connection and database health information.');
  $('#viewRoot').innerHTML=`<div class="grid settings-grid"><div class="panel"><h2>Database Connection</h2><p><strong>Status:</strong> ${configured?'Configured':'Not configured'}</p><p><strong>User:</strong> ${esc(state.user?.email||'')}</p><p><strong>Role:</strong> ${esc(state.profile?.role||'')}</p><button class="btn primary" id="healthCheck">Run Database Health Check</button></div><div class="panel"><h2>Security</h2><p class="muted">Public signup must remain disabled. Page/action permissions are enforced by Supabase RLS after running NJS_UPDATE_ROLES_PERMISSIONS.sql. Only the Owner can manage roles and user access.</p></div></div>`;
  $('#healthCheck').onclick=runDatabaseHealthCheck;
}
function subscribeRealtime(){
  if(!sb||realtimeChannel)return;
  realtimeChannel=sb.channel('business-live')
    .on('postgres_changes',{event:'*',schema:'public'},()=>{
      clearTimeout(realtimeRefreshTimer);
      realtimeRefreshTimer=setTimeout(async()=>{
        if(refreshInProgress){
          clearTimeout(realtimeRefreshTimer);
          realtimeRefreshTimer=setTimeout(()=>subscribeRealtimeRefresh(),300);
          return;
        }
        await subscribeRealtimeRefresh();
      },250);
    })
    .subscribe();
}
async function subscribeRealtimeRefresh(){
  if(refreshInProgress)return;
  refreshInProgress=true;
  try{
    await loadAll();
    render();
  }finally{
    refreshInProgress=false;
  }
}
function permissionForClick(el){
  const m=moduleForView(state.view);if(el.closest('[data-deltx],[data-deltxcat],[data-deleteclient],[data-delcatalog],[data-delcatinside],[data-dellib],[data-dellibcat],[data-delinv],[data-delmaster],[data-delrepair],[data-delproduct],[data-delsale],[data-delpayment],[data-delinvcat]'))return [m,'delete'];
  if(el.closest('[data-edittx],[data-edittxcat],[data-editclient],[data-archiveclient],[data-editcatalog],[data-editcatinside],[data-editlib],[data-editlibcat],[data-editinv],[data-repairinv],[data-editrepair],[data-editproduct],[data-editsale],[data-editpayment],[data-editexpense],[data-payexpense],[data-payrepair],[data-editinvcat],#manageInvCats,#invManageCat'))return [m,'edit'];
  if(el.closest('#addTx,#addClient,#addCatalog,#addLib,#addInv,#addRepair,#addProduct,#addSale,#addPayment,#addExpense,#addTxCategory,#addCategoryInside,#addLibCat,#addMaster,#addInvCat'))return [m,'add'];
  if(el.closest('#quickAddBtn'))return ['bookings','add'];return null;
}

function isMobileSidebar(){
  return window.matchMedia('(max-width: 900px)').matches;
}
function openMobileSidebar(){
  if(!isMobileSidebar())return;
  $('#sidebar')?.classList.add('open');
  document.body.classList.add('sidebar-open');
  let backdrop=$('#sidebarBackdrop');
  if(!backdrop){
    backdrop=document.createElement('div');
    backdrop.id='sidebarBackdrop';
    backdrop.className='sidebar-backdrop';
    document.body.appendChild(backdrop);
  }
  backdrop.classList.add('show');
}
function closeMobileSidebar(){
  $('#sidebar')?.classList.remove('open');
  document.body.classList.remove('sidebar-open');
  $('#sidebarBackdrop')?.classList.remove('show');
}
function toggleMobileSidebar(){
  if(!isMobileSidebar())return;
  if($('#sidebar')?.classList.contains('open'))closeMobileSidebar();
  else openMobileSidebar();
}

function bindGlobal(){document.addEventListener('click',e=>{const req=permissionForClick(e.target);if(req&&!can(req[0],req[1])){e.preventDefault();e.stopImmediatePropagation();requirePermission(req[0],req[1])}},true);$('#modalClose').onclick=closeModal;$('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')e.preventDefault()};document.addEventListener('click',e=>{if(e.target.matches('[data-close]'))closeModal();const v=e.target.closest('[data-view]');if(v){state.view=v.dataset.view;render();if(isMobileSidebar())closeMobileSidebar()}const b=e.target.closest('[data-business]');if(b){state.business=b.dataset.business;state.view='dashboard';state.filters.transactions={year:'',month:'',category:'',payment:''};state.filters.dashboard={year:'',month:'',category:'',payment:''};state.search.transactions='';state.search.dashboard='';render()}});$('#menuBtn').onclick=()=>toggleMobileSidebar();$('#quickAddBtn').onclick=()=>{if(requirePermission('bookings','add'))openTxForm()};$('#refreshBtn').onclick=async()=>{
  if(refreshInProgress||dataLoadPromise)return;
  refreshInProgress=true;
  const btn=$('#refreshBtn');
  const oldText=btn.textContent;
  btn.disabled=true;
  btn.textContent='↻ Refreshing…';
  status('SYNCING ALL DATA…');
  try{
    await loadAll();
    render();
    status('DATABASE CONNECTED','connected');
    toast('All system data refreshed together.');
  }catch(err){
    console.error(err);
    status('REFRESH ERROR','error');
    toast('Unable to complete the database refresh.','error');
  }finally{
    refreshInProgress=false;
    btn.disabled=false;
    btn.textContent=oldText;
  }
};$('#logoutBtn').onclick=()=>confirmModal('Sign Out','Sign out of the system?',async()=>{await sb.auth.signOut();location.reload()});$('#loginForm').onsubmit=async e=>{e.preventDefault();$('#loginMessage').textContent='Signing in…';const {data,error}=await sb.auth.signInWithPassword({email:$('#loginEmail').value.trim(),password:$('#loginPassword').value});if(error){$('#loginMessage').textContent=error.message;return}$('#loginMessage').textContent='';await signedIn(data.user)};$('#jsonFileInput').onchange=e=>{const f=e.target.files[0];if(f)validateImport(f);e.target.value=''};
  document.addEventListener('click',e=>{
    if(e.target?.id==='sidebarBackdrop')closeMobileSidebar();
  });
  document.addEventListener('keydown',e=>{
    if(e.key==='Escape'&&isMobileSidebar())closeMobileSidebar();
  });
  window.addEventListener('resize',()=>{
    if(!isMobileSidebar())closeMobileSidebar();
  });
}
init();
